#!/usr/bin/env bash
# Run from inside Laravel project: bash scripts/adjust-english-translation.sh
# Self-contained deploy script that applies the English (Melayu -> English)
# translation of the public-facing site and member UI copy to a git-less
# server copy. Idempotent; backups saved as *.i18n.bak.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
APP_ROOT="$SCRIPT_DIR"
while [ ! -f "$APP_ROOT/artisan" ] && [ "$APP_ROOT" != "/" ]; do
    APP_ROOT="$(dirname "$APP_ROOT")"
done
if [ ! -f "$APP_ROOT/artisan" ]; then
    echo "Could not locate artisan (looked upward from $SCRIPT_DIR). Run from inside the Laravel project." >&2
    exit 1
fi
cd "$APP_ROOT"

apply_blob() {
    local path="$1" b64name="$2"
    mkdir -p "$(dirname "$path")"
    local tmp
    tmp="$(mktemp)"
    if printf '%s' "${!b64name}" | base64 --decode > "$tmp" 2>/dev/null; then
        if [ -f "$path" ]; then cp "$path" "$path.i18n.bak"; fi
        mv "$tmp" "$path"
        echo "Installed: $path"
    else
        echo "Failed to decode blob for $path" >&2
        rm -f "$tmp"
    fi
}
B64_
apply_blob resources/views/components/site-layout.blade.php B64_0
B64_
apply_blob resources/views/public/home.blade.php B64_1
B64_
apply_blob resources/views/public/org-structure.blade.php B64_2
B64_
apply_blob resources/views/public/gallery.blade.php B64_3
B64_
apply_blob resources/views/member/card.blade.php B64_4
B64_
apply_blob resources/views/emails/payment-link.blade.php B64_5
B64_
apply_blob app/Mail/PaymentLinkMail.php B64_6
B64_
apply_blob database/seeders/LeadershipSeeder.php B64_7
php artisan optimize:clear >/dev/null
echo "Done: English translation deployed (backups saved as *.i18n.bak)."
